50|
51|function git(dir, args) { execFileSync("git", args, { cwd: dir, stdio: "ignore" }); }
52|
53|function repoWithFailingHook() {
54|  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "kb-hook-"));
55|  git(dir, ["init", "-q"]); git(dir, ["config", "user.email", "t@t.t"]); git(dir, ["config", "user.name", "t"]);
