3|import { useOnboarding } from './useOnboarding';
4|
5|/***
6| * MARK: useOnboarding tests
7| * @description Verifies the first-run summary hook: resolves the
8| *   GET /onboarding payload, degrades to a null summary (never a stuck
9| *   loader) when the backend is unreachable or lacks the endpoint, and
10| *   refreshes on demand after adoption.
11| */
12|vi.mock('../services/api', () => ({
13|  api: { getOnboarding: vi.fn() },
14|}));
15|
16|import { api } from '../services/api';
17|
18|afterEach(() => {
19|  vi.clearAllMocks();
20|});
21|
22|const SUMMARY = {
23|  runner: { hasFreshRunner: false, nextAction: 'approve-runner', nextActionDetail: 'Approve it.' },
24|  projectCount: 0,
25|  taskCount: 0,
26|  hasRun: false,
27|  adoptable: [{ path: '/repos/foo', name: 'foo' }],
28|  steps: [{ id: 'runner', title: 'Connect a Runner', done: false, detail: 'Approve it.' }],
29|  complete: false,
30|};
31|
32|describe('useOnboarding', () => {
33|  it('fetches the summary once on mount', async () => {
34|    api.getOnboarding.mockResolvedValue(SUMMARY);
35|    const { result } = renderHook(() => useOnboarding());
36|    expect(result.current.loading).toBe(true);
37|    await waitFor(() => {
38|      expect(result.current.loading).toBe(false);
39|    });
40|    expect(result.current.summary).toEqual(SUMMARY);
41|    expect(result.current.loaded).toBe(true);
42|    expect(api.getOnboarding).toHaveBeenCalledTimes(1);
43|  });
44|
45|  it('resolves to a null summary when the fetch fails', async () => {
46|    api.getOnboarding.mockRejectedValue(new Error('down'));
47|    const { result } = renderHook(() => useOnboarding());
48|    await waitFor(() => {
49|      expect(result.current.loading).toBe(false);
50|    });
51|    expect(result.current.summary).toBeNull();
52|    expect(result.current.loaded).toBe(false);
53|  });
54|
55|  it('stays idle until enabled flips true', async () => {
56|    api.getOnboarding.mockResolvedValue(SUMMARY);
57|    const { result, rerender } = renderHook(({ enabled }) => useOnboarding({ enabled }), {
58|      initialProps: { enabled: false },
59|    });
60|    expect(result.current.loading).toBe(false);
61|    expect(api.getOnboarding).not.toHaveBeenCalled();
62|    rerender({ enabled: true });
63|    await waitFor(() => {
64|      expect(result.current.loading).toBe(false);
65|      expect(result.current.summary).toEqual(SUMMARY);
66|    });
67|    expect(result.current.summary).toEqual(SUMMARY);
68|  });
69|
70|  it('refreshes on demand and keeps the old summary when the refresh fails', async () => {
71|    api.getOnboarding.mockResolvedValue(SUMMARY);
72|    const { result } = renderHook(() => useOnboarding());
73|    await waitFor(() => {
74|      expect(result.current.loading).toBe(false);
75|    });
76|    const updated = { ...SUMMARY, projectCount: 1 };
77|    api.getOnboarding.mockResolvedValue(updated);
78|    let next;
