    () => enabled && typeof api.getOnboarding === 'function',
  );

  useEffect(() => {
    if (!enabled || typeof api.getOnboarding !== 'function') {
      return undefined;
    }
    let isMounted = true;
    api
      .getOnboarding()
      .then((res) => {
        if (!isMounted) return;
        setSummary(res && typeof res === 'object' ? res : null);
        setLoaded(true);
      })
      .catch(() => {
        if (isMounted) setSummary(null);
      })
      .finally(() => {
        if (isMounted) setLoading(false);
      });
